mapper.update:
UPDATE model_tasks
SET task_status = #{taskStatus}
WHERE task_id = #{taskId}

mapper.select:
SELECT provider_account_id
FROM model_tasks
WHERE task_id = #{taskId}

SELECT task_status AS status, COUNT(*) AS total
FROM model_tasks
WHERE created_time >= #{from}
  AND created_time < #{toExclusive}
GROUP BY task_status
ORDER BY task_status

SELECT DATE_FORMAT(created_time, '%Y-%m-%d') AS day, COUNT(*) AS total
FROM model_tasks
WHERE created_time >= #{from}
  AND created_time < #{toExclusive}
GROUP BY DATE_FORMAT(created_time, '%Y-%m-%d')
ORDER BY day
